// RemoveTeam relationship.
// Sets o.R.Team to nil.
// Removes o from all passed in related items' relationships struct.
func (o *CTFUser) RemoveTeam(ctx context.Context, exec boil.ContextExecutor, related *CTFTeam) error {
	var err error

	queries.SetScanner(&o.TeamID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("team_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Team = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.TeamCTFUsers {
		if queries.Equal(o.TeamID, ri.TeamID) {
			continue
		}

		ln := len(related.R.TeamCTFUsers)
		if ln > 1 && i < ln-1 {
			related.R.TeamCTFUsers[i] = related.R.TeamCTFUsers[ln-1]
		}
		related.R.TeamCTFUsers = related.R.TeamCTFUsers[:ln-1]
		break
	}
	return nil
}

